def _rotl(v, c):
    return ((v << c) & 0xFFFFFFFF) | (v >> (32 - c))

def _qr(s, a, b, c, d):
    s[a] = (s[a] + s[b]) & 0xFFFFFFFF; s[d] ^= s[a]; s[d] = _rotl(s[d], 16)
    s[c] = (s[c] + s[d]) & 0xFFFFFFFF; s[b] ^= s[c]; s[b] = _rotl(s[b], 12)
    s[a] = (s[a] + s[b]) & 0xFFFFFFFF; s[d] ^= s[a]; s[d] = _rotl(s[d], 8)
    s[c] = (s[c] + s[d]) & 0xFFFFFFFF; s[b] ^= s[c]; s[b] = _rotl(s[b], 7)

def _block(key32, counter, nonce12):
    const = [0x61707865, 0x3320646E, 0x79622D32, 0x6B206574]
    state = const + list(struct.unpack('<8I', key32)) + [counter & 0xFFFFFFFF] + list(struct.unpack('<3I', nonce12))
    w = state[:]
    for _ in range(10):
        _qr(w,0,4,8,12); _qr(w,1,5,9,13); _qr(w,2,6,10,14); _qr(w,3,7,11,15)
        _qr(w,0,5,10,15); _qr(w,1,6,11,12); _qr(w,2,7,8,13); _qr(w,3,4,9,14)
    out = [(w[i]+state[i]) & 0xFFFFFFFF for i in range(16)]
    return struct.pack('<16I', *out)

def _xor(key32, nonce12, data, counter=1):
    out = bytearray(len(data)); bc = 0
    for i in range(0, len(data), 64):
        ks = _block(key32, counter+bc, nonce12)
        chunk = data[i:i+64]
        for j, b in enumerate(chunk):
            out[i+j] = b ^ ks[j]
        bc += 1
    return bytes(out)

